// ================== CAU HINH - DIEN THAT TRUOC KHI DUNG ==================
const SENSOR_CHANNEL_ID = "DIEN_CHANNEL_ID_CAM_BIEN_CUA_BAN";
const SENSOR_READ_API_KEY = "DIEN_READ_API_KEY_CAM_BIEN_CUA_BAN";
const HISTORY_RESULTS = 30;
// ===========================================================================
msg.url = `https://api.thingspeak.com/channels/${SENSOR_CHANNEL_ID}/feeds.json?api_key=${SENSOR_READ_API_KEY}&results=${HISTORY_RESULTS}`;
msg.method = 'GET';
return msg;

// Channel CAM BIEN chi co field1-4
const FIELD = { temp:'field1', humi:'field2', voltage:'field3', distance:'field4' };

function toNumber(v) { if (v === undefined || v === null || v === '') return null; const n = Number(v); return Number.isNaN(n) ? null : n; }

const feeds = (msg.payload && msg.payload.feeds) || [];

let latest = { temp: null, humi: null, voltage: null, distance: null, updatedAt: null };
for (let i = feeds.length - 1; i >= 0; i--) {
  const f = feeds[i];
  const temp = toNumber(f[FIELD.temp]);
  const humi = toNumber(f[FIELD.humi]);
  const voltage = toNumber(f[FIELD.voltage]);
  const distance = toNumber(f[FIELD.distance]);
  if (temp !== null || humi !== null || voltage !== null || distance !== null) {
    latest = { temp, humi, voltage, distance, updatedAt: f.created_at };
    break;
  }
}

const history = feeds
  .map(f => ({ createdAt: f.created_at, temp: toNumber(f[FIELD.temp]), humi: toNumber(f[FIELD.humi]) }))
  .filter(p => p.temp !== null || p.humi !== null);

node.status({ fill: 'green', shape: 'dot', text: 'OK ' + new Date().toLocaleTimeString('vi-VN') });
msg.payload = { type: 'http_data', history, latest };
return msg;

// ================== CAU HINH - DIEN THAT TRUOC KHI DUNG ==================
const COMMAND_CHANNEL_ID = "DIEN_CHANNEL_ID_LENH_CUA_BAN";
const COMMAND_READ_API_KEY = "DIEN_READ_API_KEY_LENH_CUA_BAN";
// ===========================================================================
msg.url = `https://api.thingspeak.com/channels/${COMMAND_CHANNEL_ID}/feeds.json?api_key=${COMMAND_READ_API_KEY}&results=30`;
msg.method = 'GET';
return msg;

// Channel LENH: field1 LED, field2 Relay, field3 Buzzer, field4 Che do
const FIELD = { led:'field1', relay:'field2', buzzer:'field3', mode:'field4' };
function toBool(v) { return Number(v) === 1; }

const feeds = (msg.payload && msg.payload.feeds) || [];

// Moi lan Web ghi rieng le 1 field se tao 1 dong moi (cac field con lai
// cua dong do la null). Quet nguoc tu ban ghi moi nhat ve cu, lay gia tri
// KHONG null dau tien cho TUNG field rieng biet.
//
// QUAN TRONG: neu KHONG tim thay gia tri nao trong ca so 30 ban ghi gan
// nhat (vd channel vua bi xoa lich su do sua ten field, hoac gia tri qua
// cu da troi ra ngoai cua so) thi TRA VE null cho field do - KHONG duoc tu
// y mac dinh ve false/'auto', vi Pi van co the dang giu dung trang thai that
// (Pi doc theo kieu 'khong thay thi giu nguyen', khac voi kieu cu o day la
// 'khong thay thi ve mac dinh' - gay lech giua Web va Pi, day chinh la bug
// da gap: Web tu dong nhay ve Auto/tat het dù Pi van dang o Manual/Bat).
// Ben nhan (dashboard) chi ghi de field nao khac null, giu nguyen cac field
// con lai - giong het cach Pi lam.
const deviceState = { led: null, buzzer: null, relay: null };
let mode = null;
const found = { led: false, buzzer: false, relay: false, mode: false };
for (let i = feeds.length - 1; i >= 0 && !(found.led && found.buzzer && found.relay && found.mode); i--) {
  const f = feeds[i];
  if (!found.led && f[FIELD.led] != null && f[FIELD.led] !== '') { deviceState.led = toBool(f[FIELD.led]); found.led = true; }
  if (!found.buzzer && f[FIELD.buzzer] != null && f[FIELD.buzzer] !== '') { deviceState.buzzer = toBool(f[FIELD.buzzer]); found.buzzer = true; }
  if (!found.relay && f[FIELD.relay] != null && f[FIELD.relay] !== '') { deviceState.relay = toBool(f[FIELD.relay]); found.relay = true; }
  if (!found.mode && f[FIELD.mode] != null && f[FIELD.mode] !== '') { mode = toBool(f[FIELD.mode]) ? 'manual' : 'auto'; found.mode = true; }
}

node.status({ fill: 'blue', shape: 'dot', text: (mode||'?') + ' L' + deviceState.led + ' B' + deviceState.buzzer + ' R' + deviceState.relay });
msg.payload = { type: 'state_data', deviceState, mode };
return msg;

// ================== CAU HINH - DIEN THAT TRUOC KHI DUNG ==================
const COMMAND_CHANNEL_ID = "DIEN_CHANNEL_ID_LENH_CUA_BAN";
// De bai muc do 3: NUT CHON CHE DO bat buoc dung MQTT.
// Chi 2 nut Auto/Manual di duong nay; 6 nut thiet bi di nhanh HTTP.
// field4 = Che do (0 = Auto, 1 = Manual)
const TOPIC_MAP = {
  auto:   { field: 'field4', value: '0' },
  manual: { field: 'field4', value: '1' },
};
// ===========================================================================
const cfg = TOPIC_MAP[msg.topic];
if (!cfg) { node.warn('Topic MQTT khong hop le: ' + msg.topic); return null; }

// In ra thoi diem GUI lenh MQTT (co mili giay) de doi chieu voi log ben
// Pi (chuong_trinh_pi.py -> log_event()) va tinh do tre thuc te. Luu y:
// MQTT la fire-and-forget (mqtt out khong co dau hieu xac nhan da toi
// broker/ThingSpeak), nen day la moc "gui luc", khong phai "xac nhan// thanh cong luc" nhu nhanh HTTP ben duoi.
const now = new Date();
const nowStr = now.toLocaleTimeString('vi-VN', { hour12: false }) + '.' + String(now.getMilliseconds()).padStart(3, '0');
node.warn(`[${nowStr}] GUI LENH MQTT: ${msg.topic} = ${cfg.value}`);

msg.topic = `channels/${COMMAND_CHANNEL_ID}/publish/fields/${cfg.field}`;
msg.payload = cfg.value;
return msg;

// ================== CAU HINH - DIEN THAT TRUOC KHI DUNG ==================
const COMMAND_WRITE_API_KEY = "DIEN_WRITE_API_KEY_LENH_CUA_BAN";
// De bai muc do 3: NUT DIEU KHIEN bat buoc dung HTTP.
// Ca 6 nut LED / Relay / Buzzer (Bat lan Tat) deu di duong nay.
// field1 = LED, field2 = Relay, field3 = Buzzer
const TOPIC_MAP = {
  led_on:     { field: 'field1', value: '1' },
  led_off:    { field: 'field1', value: '0' },
  relay_on:   { field: 'field2', value: '1' },
  relay_off:  { field: 'field2', value: '0' },
  buzzer_on:  { field: 'field3', value: '1' },
  buzzer_off: { field: 'field3', value: '0' },
};
// ===========================================================================
const cfg = TOPIC_MAP[msg.topic];
if (!cfg) { node.warn('Topic HTTP khong hop le: ' + msg.topic); return null; }

msg.url = 'https://api.thingspeak.com/update.json';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
// Node "http request" duoc dat ret='obj' nen sau khi goi xong no GHI DE
// msg.payload bang noi dung phan hoi. Duong thu lai dua chinh msg do quay
// nguoc vao node POST, nen neu chi de than request o msg.payload thi tu lan
// thu 2 tro di se gui di phan hoi cu ("0") - mat ca api_key lan field, va
// KHONG BAO GIO thanh cong duoc. Vi vay cat ban goc sang msg.cmdBody (node
// http request khong dung den truong nay) de duong thu lai khoi phuc lai.
msg.cmdBody = { api_key: COMMAND_WRITE_API_KEY, [cfg.field]: cfg.value };
msg.payload = msg.cmdBody;
msg.attempt = 1;
return msg;

// ThingSpeak gioi han toi thieu 15s giua 2 lan ghi len CUNG 1 channel (channel
// nay cung duoc Raspberry Pi ghi trung binh cam bien moi 20s, va cac nut khac
// cung ghi len day, nen de trung nhip) - khi bi tu choi, ThingSpeak tra ve HTTP
// 200 kem noi dung "0" (khong phai loi HTTP), nen phai kiem tra entry_id thay
// vi chi dua vao ma trang thai HTTP.
// Pi ghi trung binh cam bien moi ~20s cung len channel nay, ma ThingSpeak
// chi cho ghi 15s/lan -> moi chu ky chi con ~5-6s trong cho lenh nut bam.
// Vi vay thu lai 10 lan x 3s (~30s) de chac chan phu tron it nhat 1 chu ky.
const MAX_ATTEMPTS = 10;
const ok = msg.payload && typeof msg.payload === 'object' && Number(msg.payload.entry_id) > 0;

if (ok) {
  const now = new Date();
  const nowStr = now.toLocaleTimeString('vi-VN', { hour12: false }) + '.' + String(now.getMilliseconds()).padStart(3, '0');
  node.status({ fill: 'green', shape: 'dot', text: 'OK ' + nowStr });
  // Moc thoi gian GUI THANH CONG len ThingSpeak (co mili giay) - doi chieu
  // voi log ben Pi (log_event() trong chuong_trinh_pi.py) de tinh do tre.
  node.warn(`[${nowStr}] GUI THANH CONG len ThingSpeak (HTTP): ${msg.topic} entry_id=${msg.payload.entry_id}`);
  return [{ payload: { type: 'cmd_ok', topic: msg.topic } }, null, null];
}
if (msg.attempt < MAX_ATTEMPTS) {
  node.warn(`Gui lenh dieu khien loi (lan ${msg.attempt}), thu lai sau 3s...`);
  node.status({ fill: 'yellow', shape: 'ring', text: 'Thu lai lan ' + (msg.attempt + 1) });
  msg.attempt += 1;
  // Tra lai than request goc (msg.payload dang la phan hoi that bai cua lan
  // vua roi) - neu khong, lan thu lai se POST di chinh phan hoi do.
  msg.payload = msg.cmdBody;
  return [null, msg, null];
}
node.status({ fill: 'red', shape: 'ring', text: 'That bai sau ' + MAX_ATTEMPTS + ' lan' });
node.warn('Gui lenh dieu khien that bai sau nhieu lan thu (co the do gioi han 15s/lan ghi cua ThingSpeak)');
// Bao that bai ve cho dashboard hien thong bao ro rang, thay vi im lang
// tra ve trang thai cu o lan doc lai tiep theo khien nguoi dung tuong tu
// nhien no doi lai.
return [null, null, { payload: { type: 'cmd_failed', topic: msg.topic } }];
